import csv, re

with open("/app/dataset/people_accounts.csv") as f:
    reader = csv.DictReader(f)
    people_accounts = {f"{row[\"first_name\"]} {row[\"last_name\"]}": int(row["account_balance"]) for row in reader}

with open("/app/dataset/genealogy_trees.txt") as f:
    lines = [line.rstrip("\n") for line in f]

# Find all occurrences of people
found = {}
for name in people_accounts:
    fn, ln = name.split(" ", 1)
    # Check 1: full name on single line
    for r, line in enumerate(lines):
        idx = 0
        while True:
            pos = line.find(name, idx)
            if pos == -1:
                break
            found[name] = (r, pos, name)
            idx = pos + 1
    if name in found:
        continue
    # Check 2: fn on line r, ln on line r+1 or r+2
    for r in range(len(lines) - 1):
        if fn in lines[r]:
            idx = 0
            while True:
                pos = lines[r].find(fn, idx)
                if pos == -1:
                    break
                # search in lines[r+1] or lines[r+2] near pos
                for dr in [1, 2]:
                    if r + dr < len(lines):
                        # check window [pos-15, pos+len(fn)+15]
                        w_start = max(0, pos - 15)
                        w_end = min(len(lines[r+dr]), pos + len(fn) + 15)
                        sub = lines[r+dr][w_start:w_end]
                        if ln in sub:
                            found[name] = (r, pos, f"{fn}\n{ln}")
                            break
                if name in found:
                    break
                idx = pos + 1
        if name in found:
            break

print(f"Total people found: {len(found)} / {len(people_accounts)}")

# Group people by row
by_row = {}
for name, (r, c, txt) in found.items():
    by_row.setdefault(r, []).append((c, name))

for r in sorted(by_row.keys()):
    print(f"Row {r:2d}: {len(by_row[r])} people: {sorted(by_row[r])[:3]}...")
'

